// SR-132 write-direction prefix.
// Decorates the relayed text with [facilitator] / [AI] so Slack
// readers can tell who is speaking. Validates the source field;
// unknown values are rejected with an error so an upstream typo
// shows up at smoke time rather than as silently-mislabelled
// posts in Slack.
const body = $json.body || {};
const source = body.source;
const text = body.text;

if (typeof text !== 'string' || text === '') {
  throw new Error('chat-to-slack: missing or empty text');
}
let prefix;
if (source === 'facilitator') prefix = '[facilitator] ';
else if (source === 'ai') prefix = '[AI] ';
else throw new Error('chat-to-slack: invalid source ' + JSON.stringify(source));

return [{ json: { decoratedText: prefix + text } }];
